import React from 'react';

// This is the SVG version of your logo, converted into a React component.
// We can pass `className` as a prop to control its size and color from the outside.
const Logo = ({ className }) => (
  <svg
    className={className}
    viewBox="0 0 100 100" // A 100x100 canvas for the design
    fill="currentColor" // The color will be inherited (e.g., from text-primary)
    xmlns="http://www.w3.org/2000/svg"
  >
    {/* The main book shape */}
    <path d="M50 35c-15 0-25 10-25 25h50c0-15-10-25-25-25z" fill="none" />
    <path d="M15 75v-30c0-11 9-20 20-20h30c11 0 20 9 20 20v30H15z" />
    {/* Book pages */}
    <path fill="#FFF" d="M50 30v40h-25c-5.5 0-10-4.5-10-10V40c0-5.5 4.5-10 10-10h25z" />
    <path fill="#FFF" d="M50 30v40h25c5.5 0 10-4.5 10-10V40c0-5.5-4.5-10-10-10h-25z" />
    {/* Page lines */}
    <path stroke="currentColor" strokeWidth="2" d="M30 40h15m5 0h15M30 45h15m5 0h15M30 50h15m5 0h15M30 55h15m5 0h15M30 60h15m5 0h15" />

    {/* Graduation Cap */}
    <path fill="#FFF" d="M50 15L25 25l25 10 25-10L50 15z" />
    <path fill="#FFF" d="M45 35v5h10v-5h-10z" />
    <rect x="20" y="24" width="60" height="3" fill="#FFF" />

    {/* Orbit path */}
    <path d="M10 60 C 20 40, 80 40, 90 60" stroke="#FFF" strokeWidth="3" fill="none" />
    {/* Orbiting dot */}
    <circle cx="15" cy="48" r="3" fill="#FFF" />
    <circle cx="85" cy="48" r="2" fill="#FFF" />
    <circle cx="65" cy="38" r="1.5" fill="#FFF" />
  </svg>
);

export default Logo;
